import {cargoDetails,validateCargo,validQuantity} from './cargo-data.js';
import {weight} from './load.js';
import {loseCrew} from './crew.js';
import {ammoAllowed} from './weapons.js';
export const stationDefaults = {Bridge:5,Rudder:3,Mast:5,'Gun Deck':8,'Powder Dock':3,Anchors:3,Infirmary:3,Larder:3,Hold:5};
export const sectionOrder=['Bridge','Mast','Gun Deck','Powder Dock','Infirmary','Larder','Hold','Anchors','Rudder'];
export const services = {Bridge:'Command and helm',Rudder:'Steering',Mast:'Sail propulsion','Gun Deck':'Gunnery','Powder Dock':'Ammunition supply',Anchors:'Anchoring',Infirmary:'Medical care',Larder:'Food storage service',Hold:'Cargo storage service'};
export function newShip(id='sea-wren',name='Sea Wren'){return {id,name,type:'Large Sloop',minCrew:5,maxCrew:48,maxGuns:9,capacityUnits:150,archived:false,hull:20,maxHull:20,crew:16,crewLevel:1,sails:1,sinking:null,stations:Object.fromEntries(Object.entries(stationDefaults).map(([k,max])=>[k,{hp:max,max,assigned:0}])),guns:Array.from({length:4},(_,i)=>({id:`gun-${i+1}`,name:`${i<2?'Port':'Starboard'} ${i%2+1}`,side:i<2?'Port':'Starboard',condition:'operational',loaded:'Lead shot - light',loadedCargo:{cargoUnits:1/16,quantityUnit:'item',catalogId:'shot-lead-light',rarity:'Common',marketValue:4,marketValueMax:null,ammoSize:'light',shotType:'lead'},assigned:0})),inventory:[{id:'lead',name:'Lead shot - light',category:'Ammunition',quantity:26,cargoUnits:1/16,quantityUnit:'item',catalogId:'shot-lead-light',rarity:'Common',marketValue:4,marketValueMax:null,ammoSize:'light',shotType:'lead'}],officers:{Captain:'',Gunner:'','First Mate':'',Helmsman:'',Bosun:'',Surgeon:'',Chaplain:'',Carpenter:'',Navigator:'',Lookout:'',Quartermaster:'',Cook:''}};}
export function initialState(){return {version:1,selected:'sea-wren',ships:[newShip()],log:[]};}
export function assigned(ship){return Object.values(ship.stations).reduce((n,s)=>n+s.assigned,0)+ship.guns.reduce((n,g)=>n+g.assigned,0);}
export function apply(ship,action){const s=structuredClone(ship);const g=s.guns.find(g=>g.id===action.id);const n=Number(action.amount);switch(action.type){
case 'sails': if(![0,1,2].includes(n))throw Error('Choose a sail state.');s.sails=n;break;
case 'hp': {if(!Number.isInteger(n))throw Error('Enter a whole HP amount.');if(action.id==='Hull'){s.hull=Math.max(0,Math.min(s.maxHull,s.hull+n));}else {const st=s.stations[action.id];if(!st)throw Error('Unknown section.');st.hp=Math.max(0,Math.min(st.max,st.hp+n));}break;}
case 'fire': if(!g||g.condition!=='operational'||!g.loaded)throw Error('This cannon is not ready.');if(s.stations['Gun Deck'].hp===0)throw Error('The gun deck is destroyed.');g.loaded=null;g.loadedUnitWeight=null;g.loadedCargo=null;break;
case 'reload': {if(!g||g.condition!=='operational'||g.loaded)throw Error('This cannon cannot reload.');if(!s.stations['Powder Dock'].hp||!s.stations['Gun Deck'].hp)throw Error('Restore the gun deck and powder dock before reloading.');const ammo=s.inventory.find(i=>i.id===action.ammo);if(!ammo||ammo.category!=='Ammunition'||ammo.quantity<1)throw Error('No ammunition available.');if(!ammoAllowed(g,ammo))throw Error('Swivel guns may only load lead shot.');ammo.quantity--;g.loaded=ammo.name;g.loadedUnitWeight=ammo.unitWeight??null;g.loadedCargo=cargoDetails(ammo);break;}
case 'gun-condition':if(!g||!['operational','disabled','destroyed'].includes(action.value))throw Error('Invalid cannon condition.');g.condition=action.value;break;
case 'inventory':{const item=s.inventory.find(i=>i.id===action.id);if(!item||!Number.isFinite(n)||!validQuantity(item,Number((item.quantity+n).toPrecision(15))))throw Error('Quantity must be a nonnegative whole number.');item.quantity=Number((item.quantity+n).toPrecision(15));break;}
case 'remove-item':if(!s.inventory.some(i=>i.id===action.id))throw Error('Item no longer exists.');s.inventory=s.inventory.filter(i=>i.id!==action.id);break;
case 'add-item':{const data=validateCargo(action);if(!validQuantity(data,n)||n<=0)throw Error('Enter a positive quantity; individual items require whole numbers.');s.inventory.push({id:action.id,...data,quantity:n});break;}
case 'edit-item':{const item=s.inventory.find(i=>i.id===action.id);if(!item||!action.name?.trim())throw Error('Choose an item and enter its name.');const data=validateCargo(action);if(!validQuantity(data,action.quantity??item.quantity))throw Error('Quantity must match the chosen item or cargo-unit basis.');Object.assign(item,data,{quantity:action.quantity??item.quantity});break;}
case 'loaded-weight':if(!g?.loaded)throw Error('There is no loaded round.');{const data=validateCargo({...action.cargo,name:action.cargo?.name??g.loaded,category:'Ammunition',quantityUnit:'item'});if(data.ammoSize&&!ammoAllowed(g,data))throw Error('Swivel guns require lead or swivel shot.');g.loaded=data.name;g.loadedCargo={...cargoDetails(g.loadedCargo??{}),...cargoDetails(data)};}break;
case 'crew-loss':return loseCrew(s,action.losses);
case 'end-sinking':if(s.hull<=0)throw Error('Restore hull HP before ending the sinking countdown.');s.sinking=null;break;
case 'crew':if(!Number.isInteger(n)||n<0||n>(s.maxCrew??48)||n<assigned(s))throw Error(`Crew must cover assignments and stay within 0–${s.maxCrew??48}.`);s.crew=n;break;
case 'assign':if(!Number.isInteger(n)||n<0)throw Error('Enter a nonnegative whole crew count.');if(g)g.assigned=n;else if(s.stations[action.id])s.stations[action.id].assigned=n;else throw Error('Unknown station.');if(assigned(s)>s.crew)throw Error('Not enough unassigned crew.');break;
case 'officer':if(!(action.id in s.officers))throw Error('Unknown role.');s.officers[action.id]=action.value.slice(0,80);break;
case 'sinking':if(!Number.isInteger(n)||n<0||n>12)throw Error('Enter 0–12 turns.');s.sinking=n;break;
default:throw Error('Unknown action.');}return s;}
